//go:build goexperiment.simd

// Package ontology registers the frozen MITRE ATT&CK (enterprise, ICS, mobile)
// crossed with D3FEND tables — generated by cmd/d3fendgen into attack_gen.go —
// into a gr4ph builder.
//
// The generated file carries the pinned source names and the table sizes; see
// the Source* and N* constants in attack_gen.go. Regenerate with `make gen`
// (network required once) and commit the result.
package ontology

import (
	"errors"
	"fmt"

	"github.com/fr0g-66723067-io/gr4ph"
)

// ErrBuilderNotEmpty is returned by Register when the builder already holds
// relations or nodes.
var ErrBuilderNotEmpty = errors.New("ontology: Register requires a fresh builder")

// Register adds every relation, node, hierarchy link and edge of the frozen
// tables to b, and returns the first error.
//
// The registration order is load-bearing: the builder assigns dense ids in
// registration order, so
//
//   - RelNames[i] / DefRelNames[i] must become plane i+1, matching the
//     generated Rel*/DefRel* constants;
//   - TacticIDs[i] / PlatformNames[i] must become attribute index i, matching
//     the emitted TacticTTP/PlatformTTP rows;
//   - TTPIDs[i] must become technique index i, which makes TTPParents[i] a
//     valid direct index (parents sort before, and register before, their
//     children) and keeps every child block contiguous;
//   - the KEV partition registers last, because nothing else indexes into it
//     and its own arrays fix the dense ids of its three partitions
//     (KEVIDs/CWEIDs/KEVProductNames order).
//
// Register requires a fresh, unbuilt builder: pre-registered relations or nodes
// would shift every dense id and silently misalign the tables, so an
// already-built or non-empty builder returns ErrBuilderNotEmpty.
//
// Callers own the builder; use NewBuilder, Register, Build for the frozen
// engine.
func Register(b *gr4ph.Builder) error {
	if b.Built() || b.TTPCount() != 0 || b.ArtifactCount() != 0 || b.CountermeasureCount() != 0 ||
		b.RelCount() != 0 || b.DefRelCount() != 0 || b.TacticCount() != 0 || b.PlatformCount() != 0 ||
		b.DataComponentCount() != 0 || b.GroupCount() != 0 ||
		b.KEVCount() != 0 || b.CWECount() != 0 || b.ProductCount() != 0 {
		return ErrBuilderNotEmpty
	}
	for _, name := range RelNames {
		if _, err := b.AddRel(name); err != nil {
			return fmt.Errorf("relation %s: %w", name, err)
		}
	}
	for _, name := range DefRelNames {
		if _, err := b.AddDefRel(name); err != nil {
			return fmt.Errorf("defensive relation %s: %w", name, err)
		}
	}
	// The attribute vocabularies register before the techniques because the
	// emitted TacticTTP/PlatformTTP rows are indexed by these dense ids.
	for i, id := range TacticIDs {
		if _, err := b.AddTactic(id, TacticLabels[i]); err != nil {
			return fmt.Errorf("tactic %s: %w", id, err)
		}
	}
	for _, name := range PlatformNames {
		if _, err := b.AddPlatform(name); err != nil {
			return fmt.Errorf("platform %s: %w", name, err)
		}
	}

	for i, id := range TTPIDs {
		parent := gr4ph.TTP(TTPParents[i])
		if _, err := b.AddTTP(id, TTPLabels[i], TTPDomains[i], parent, TTPRevoked[i], TTPAliases[i]...); err != nil {
			return fmt.Errorf("technique %s: %w", id, err)
		}
	}
	for i, name := range ArtifactNames {
		if _, err := b.AddArtifact(name, ArtifactLabels[i]); err != nil {
			return fmt.Errorf("artifact %s: %w", name, err)
		}
	}
	for i, id := range CountermeasureIDs {
		if _, err := b.AddCountermeasure(id, CountermeasureLabels[i]); err != nil {
			return fmt.Errorf("countermeasure %s: %w", id, err)
		}
	}
	for i, id := range DataComponentIDs {
		if _, err := b.AddDataComponent(id, DataComponentLabels[i]); err != nil {
			return fmt.Errorf("data component %s: %w", id, err)
		}
	}
	for i, id := range GroupIDs {
		if _, err := b.AddGroup(id, GroupLabels[i], GroupKinds[i]); err != nil {
			return fmt.Errorf("group %s: %w", id, err)
		}
	}

	for i := range OffEdgeTTP {
		if err := b.AddEdge(gr4ph.TTP(OffEdgeTTP[i]), gr4ph.Artifact(OffEdgeArt[i]), gr4ph.Rel(OffEdgeRel[i])); err != nil {
			return fmt.Errorf("offensive edge %d: %w", i, err)
		}
	}
	for i := range DefEdgeCM {
		if err := b.AddDefEdge(gr4ph.Countermeasure(DefEdgeCM[i]), gr4ph.Artifact(DefEdgeArt[i]), gr4ph.DefRel(DefEdgeRel[i])); err != nil {
			return fmt.Errorf("defensive edge %d: %w", i, err)
		}
	}
	for i := range DefendsCM {
		if err := b.AddDefendsEdge(gr4ph.Countermeasure(DefendsCM[i]), gr4ph.TTP(DefendsTTP[i])); err != nil {
			return fmt.Errorf("defends-against pair %d: %w", i, err)
		}
	}
	for i := range TacticTTP {
		for _, t := range TacticTTP[i] {
			if err := b.AddTacticEdge(gr4ph.TTP(t), gr4ph.Tactic(i)); err != nil {
				return fmt.Errorf("tactic assignment %d/%d: %w", i, t, err)
			}
		}
	}
	for i := range PlatformTTP {
		for _, t := range PlatformTTP[i] {
			if err := b.AddPlatformEdge(gr4ph.TTP(t), gr4ph.Platform(i)); err != nil {
				return fmt.Errorf("platform assignment %d/%d: %w", i, t, err)
			}
		}
	}
	for i := range DetectsDC {
		if err := b.AddDetectsEdge(gr4ph.DataComponent(DetectsDC[i]), gr4ph.TTP(DetectsTTP[i])); err != nil {
			return fmt.Errorf("detects pair %d: %w", i, err)
		}
	}
	for i := range UsesGroup {
		if err := b.AddGroupUsesEdge(gr4ph.Group(UsesGroup[i]), gr4ph.TTP(UsesTTP[i])); err != nil {
			return fmt.Errorf("uses pair %d: %w", i, err)
		}
	}
	for i := range SoftwareUseGroup {
		if err := b.AddGroupSoftwareEdge(gr4ph.Group(SoftwareUseGroup[i]), gr4ph.Group(SoftwareUseTarget[i])); err != nil {
			return fmt.Errorf("software-use pair %d: %w", i, err)
		}
	}

	// The KEV catalog registers last: nothing else indexes into it, and its own
	// emitted arrays fix the dense ids of all three of its partitions.
	for _, id := range CWEIDs {
		if _, err := b.AddCWE(id, id); err != nil {
			return fmt.Errorf("cwe %s: %w", id, err)
		}
	}
	for i, name := range KEVProductNames {
		if _, err := b.AddProduct(KEVProductVendors[i], name); err != nil {
			return fmt.Errorf("product %s/%s: %w", KEVProductVendors[i], name, err)
		}
	}
	for i, id := range KEVIDs {
		if _, err := b.AddKEV(id, KEVNames[i], KEVAdded[i], KEVRansomware[i]); err != nil {
			return fmt.Errorf("kev %s: %w", id, err)
		}
	}
	for i := range KEVWeaknessKEV {
		if err := b.AddKEVWeaknessEdge(gr4ph.KEV(KEVWeaknessKEV[i]), gr4ph.CWE(KEVWeaknessCWE[i])); err != nil {
			return fmt.Errorf("kev weakness %d: %w", i, err)
		}
	}
	for i, p := range KEVProductIndex {
		if err := b.AddKEVProductEdge(gr4ph.KEV(i), gr4ph.Product(p)); err != nil {
			return fmt.Errorf("kev product %d: %w", i, err)
		}
	}
	return nil
}
